export const EDITOR_BYLINE = 'By Mark Putiyon, Editor-in-Chief'
export const EDITOR_NAME = 'Mark Putiyon'
export const EDITOR_BIO =
  'Mark Putiyon is Editor-in-Chief of BestBotFor. He’s a CTO and technology executive who has worked with small businesses for 30 years, helping them choose and run the right technology. BestBotFor’s scores are based on research, not hands-on testing: we check each tool’s own pricing and feature pages and published sources, so you can pick the right AI in 30 seconds.'

export function getCategoryGuide(category: string): CategoryGuide | undefined {
  return CATEGORY_GUIDES.find((guide) => guide.category === category)
}

/** Article JSON-LD for a category guide, with Mark as the author. */
export function categoryGuideArticleJsonLd(guide: CategoryGuide) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: guide.heading,
    description: guide.description,
    url: absoluteUrl(`/guides/${guide.category}`),
    dateModified: guide.checked,
    author: { '@type': 'Person', name: EDITOR_NAME, jobTitle: 'Editor-in-Chief', url: absoluteUrl('/about') },
    publisher: { '@type': 'Organization', name: SITE_NAME },
  }
}

